def build_constraint_1(qc, problem_qubits, flag, scratch):
    # match at offset 0: bits 0..4 must all be 0
    # Invert bits, check all are 1, then invert back
    for i in range(5):
        qc.x(problem_qubits[i])
    qc.mcx(problem_qubits[0:5], flag, mode='noancilla')
    for i in range(5):
        qc.x(problem_qubits[i])

