    qc.mcx(problem_qubits[2:7], flag, mode='noancilla')
    for i in range(2, 7):
        qc.x(problem_qubits[i])

def build_constraint_4(qc, problem_qubits, flag, scratch):
    # match at offset 3: bits 3..7 must all be 0
    for i in range(3, 8):
        qc.x(problem_qubits[i])
    qc.mcx(problem_qubits[3:8], flag, mode='noancilla')
    for i in range(3, 8):
        qc.x(problem_qubits[i])
