def build_constraint_1(qc, problem_qubits, flag, scratch):
    offset = 0
    pattern = [1, 1, 0, 1]
    # borrow two free qubits: indices not in [offset, offset+3]
    anc1 = problem_qubits[4]
    anc2 = problem_qubits[5]
    qubits = [problem_qubits[offset + i] for i in range(4)]

    # compute AND of qubits 0 and 1 (with pattern inversion where needed)
    for i in range(2):
        if pattern[i] == 0:
