def build_constraint_1(qc, problem_qubits, flag, scratch):
    # Five masks for the subsets whose sum equals 104
    masks = [
        [0,0,0,1,1,1,1,1],  # {40,28,20,9,7}
        [0,1,0,1,0,1,0,1],  # {40,37,20,7}
        [1,0,1,1,0,1,1,1],  # {40,20,18,10,9,7}
        [0,1,1,1,1,0,1,0],  # {37,28,20,10,9}
        [1,1,0,0,0,1,1,0]   # {18,37,40,9}
    ]
    num_cond = len(masks)

    # ------------------------------------------------------------
    # Step 1: Compute each condition into scratch[0..num_cond-1]
    # ------------------------------------------------------------
    for j, mask in enumerate(masks):
        target = scratch[j]
        # Flip problem qubits where mask bit is 0
        for i, bit in enumerate(mask):
            if bit == 0:
                qc.x(problem_qubits[i])
        # multi‑controlled X: target becomes 1 iff all problem qubits are 1
        qc.mcx(problem_qubits, target, mode='noancilla')
        # Restore problem qubits
        for i, bit in enumerate(mask):
            if bit == 0:
                qc.x(problem_qubits[i])

    # ------------------------------------------------------------
    # Step 2: Flip flag iff OR of condition bits
    #         (using AND on inverted condition bits)
    # ------------------------------------------------------------
    # Invert all condition bits
    for j in range(num_cond):
        qc.x(scratch[j])
    # multi‑controlled Toffoli: flip flag if all condition bits are 1
    qc.mcx(scratch[:num_cond], flag, mode='noancilla')
    # Complement the effect: now flag is flipped iff any condition was 1
    qc.x(flag)
    # Restore condition bits (undo inversion)
    for j in range(num_cond):
        qc.x(scratch[j])

    # ------------------------------------------------------------
    # Step 3: Uncompute condition bits (repeat the forward circuit)
    # ------------------------------------------------------------
    for j, mask in enumerate(masks):
        target = scratch[j]
        for i, bit in enumerate(mask):
            if bit == 0:
                qc.x(problem_qubits[i])
        qc.mcx(problem_qubits, target, mode='noancilla')
        for i, bit in enumerate(mask):
            if bit == 0:
                qc.x(problem_qubits[i])
