def build_constraint_1(qc, problem_qubits, flag, scratch):
    # Clause: (x1 OR x6 OR NOT x7)
    # Literals: x1 (pos), x6 (pos), x7 (neg)
    indices = [1, 6, 7]
    neg = [False, False, True]
    # Use scratch[0] as temporary ancilla
    anc = scratch[0]

    # Apply X on qubits representing positive literals (to negate them for AND)
    for i, n in zip(indices, neg):
        if not n:
            qc.x(problem_qubits[i])

    # Compute AND of the three (now negated) literals: first two into anc, then into flag
    qc.ccx(problem_qubits[indices[0]], problem_qubits[indices[1]], anc)
    qc.ccx(anc, problem_qubits[indices[2]], flag)
    # Uncompute anc
    qc.ccx(problem_qubits[indices[0]], problem_qubits[indices[1]], anc)

    # Restore problem qubits
    for i, n in zip(indices, neg):
        if not n:
            qc.x(problem_qubits[i])

    # Invert flag: we want flip when clause is satisfied (OR is true)
    qc.x(flag)


def build_constraint_2(qc, problem_qubits, flag, scratch):
    # Clause: (NOT x0 OR NOT x3 OR NOT x4)
    indices = [0, 3, 4]
    neg = [True, True, True]  # all negated
    anc = scratch[0]

    for i, n in zip(indices, neg):
        if not n:
            qc.x(problem_qubits[i])

    qc.ccx(problem_qubits[indices[0]], problem_qubits[indices[1]], anc)
    qc.ccx(anc, problem_qubits[indices[2]], flag)
    qc.ccx(problem_qubits[indices[0]], problem_qubits[indices[1]], anc)

    for i, n in zip(indices, neg):
        if not n:
            qc.x(problem_qubits[i])

    qc.x(flag)


